// Map GHL opportunity fields to Snowflake target columns.
// Each input item is one opportunity from the Split Out node.
const items = $input.all();
const mapped = items.map(item => {
  const opp = item.json;
  return {
    json: {
      OPPORTUNITY_ID: opp.id || null,
      LOCATION_ID: opp.locationId || null,
      CONTACT_ID: opp.contact?.id || null,
      CONTACT_NAME: opp.contact?.name || null,
      CONTACT_EMAIL: opp.contact?.email || null,
      CONTACT_PHONE: opp.contact?.phone || null,
      PIPELINE_ID: opp.pipelineId || null,
      PIPELINE_STAGE_ID: opp.pipelineStageId || null,
      PIPELINE_NAME: opp.pipeline?.name || null,
      STAGE_NAME: opp.pipelineStage?.name || null,
      STATUS: opp.status || null,
      MONETARY_VALUE: opp.monetaryValue != null ? Number(opp.monetaryValue) : null,
      SOURCE: opp.source || null,
      ASSIGNED_TO: opp.assignedTo || null,
      CREATED_AT: opp.createdAt || null,
      UPDATED_AT: opp.updatedAt || null,
      LAST_STATUS_CHANGE_AT: opp.lastStatusChangeAt || null,
      LAST_STAGE_CHANGE_AT: opp.lastStageChangeAt || null,
      NAME: opp.name || null,
      _LOADED_AT: new Date().toISOString()
    }
  };
});
return mapped;
